 "content": "def transform(grid):
    """Extract the upper-left quadrant of the largest symmetric square motif."""
    h, w = len(grid), len(grid[0])
    best = None
    # The motif is mirrored across both its horizontal and vertical midlines.
    for side in range(min(h, w), 1, -1):
        for r in range(h - side + 1):
            for c in range(w - side + 1):
                square = [row[c:c + side] for row in grid[r:r + side]]
                if any(square[i][j] != square[side - 1 - i][j]
                       for i in range(side) for j in range(side)):
                    continue
                if any(square[i][j] != square[i][side - 1 - j]
                       for i in range(side) for j in range(side)):
                    continue
                # Prefer the most informative symmetric square when empty
                # margins permit multiple equivalent placements.
                score = sum(value != 0 for row in square for value in row)
                candidate = (score, -r, -c, square)
                if best is None or candidate[:3] > best[:3]:
                    best = candidate
        if best is not None:
            half = side // 2
            return [row[:half] for row in best[3][:half]]
    raise ValueError("No symmetric square motif found")

